from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LowVolatilityTilting(Strategy):
    rationale = (
        "Historically, low-volatility stocks have shown to have superior risk-adjusted returns. "
        "By tilting the portfolio towards these stocks, we aim to capture this effect."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.is_empty():
            return Signal(information_available_at=stamp, weights={})

        symbols = [str(s) for s in view.symbols]
        avg_volatility = (
            history.filter(pl.col("symbol").is_in(symbols))
            .select(
                pl.col("symbol"),
                (pl.col("adj_close") / pl.col("adj_close").shift(1) - 1.0).alias("return")
            )
            .group_by("symbol", sort=True)
            .agg((pl.col("return").std().alias("volatility")))
            .sort(by="volatility")
        )

        if avg_volatility.height < len(symbols):
            return Signal(information_available_at=stamp, weights={})

        picks = [str(row["symbol"]) for row in avg_volatility.head(len(symbols))]
        weight = 1.0 / len(picks)
        return Signal(
            information_available_at=stamp, weights={s: weight for s in picks}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
